#!/usr/bin/env bash
# Bootstrap the Firecracker vmm dumbo/virtio fuzz harness.
# Run from the repository ROOT (the folder that contains src/vmm), on the
# checked-out v1.18.0 (or firecracker-v1.18) tree.
set -euo pipefail

if [ ! -d src/vmm/src ]; then
  echo "ERROR: run this from the Firecracker repo root (no src/vmm/src here)." >&2
  exit 1
fi

echo "[1/2] Writing src/vmm/fuzz/ ..."
base64 -d > /tmp/_fcfuzz.tar <<'B64EOF'

B64EOF
tar -xf /tmp/_fcfuzz.tar -C src/vmm
rm -f /tmp/_fcfuzz.tar

echo "[2/2] Patching src/vmm/src/devices/virtio/vsock/mod.rs ..."
MODRS=src/vmm/src/devices/virtio/vsock/mod.rs
if grep -q 'cfg(feature = "fuzzing")\] *$' "$MODRS" 2>/dev/null || grep -qF 'pub mod packet;' "$MODRS"; then
  echo "    already patched, skipping."
else
  perl -0pi -e 's/^mod packet;$/#[cfg(not(feature = "fuzzing"))]\nmod packet;\n#[cfg(feature = "fuzzing")]\npub mod packet;/m' "$MODRS"
  echo "    done."
fi

echo
echo "OK. Next:"
echo "  cd src/vmm && cargo +nightly fuzz build block_request"
